// Extrai apenas nome e tipo do arquivo. O conteudo em si nao vai no payload:
// o fluxo 01 baixa o arquivo por conta propria a partir da fileUrl.
const binario = $input.item.binary.data;
const mimeType = binario.mimeType || 'application/pdf';
const extensao = (mimeType.split('/')[1] || 'pdf').split(';')[0];

let fileName = binario.fileName || `documento_whatsapp.${extensao}`;

// O WhatsApp costuma anexar "-filename*=..." ao nome; corta isso fora.
if (fileName.includes('-filename')) {
  fileName = fileName.split('-filename')[0];
}
// Evita nomes duplicados tipo "arquivo.pdf.pdf"
fileName = fileName.replace(/\.(pdf|ofx|csv|jpg|jpeg|png)\.\1$/i, '.$1');

return [{ json: { fileName, mimeType } }];

